251	  get size(): number {
252	    return this.costs.length;
253	  }
254	
255	  push(cost: number, index: number): void {
256	    this.costs.push(cost);
257	    this.indexes.push(index);
258	    let child = this.costs.length - 1;
259	    while (child > 0) {
260	      const parent = (child - 1) >> 1;
261	      if (this.costs[parent]! <= cost) break;
262	      this.swap(child, parent);
263	      child = parent;
264	    }
265	  }
266	
267	  pop(): [number, number] {
268	    const top: [number, number] = [this.costs[0]!, this.indexes[0]!];
269	    const lastCost = this.costs.pop()!;
270	    const lastIndex = this.indexes.pop()!;
271	    if (this.costs.length > 0) {
272	      this.costs[0] = lastCost;
273	      this.indexes[0] = lastIndex;
274	      let parent = 0;
275	      for (;;) {
276	        const left = 2 * parent + 1;
277	        const right = left + 1;
278	        let smallest = parent;
279	        if (left < this.costs.length && this.costs[left]! < this.costs[smallest]!) smallest = left;
280	        if (right < this.costs.length && this.costs[right]! < this.costs[smallest]!) smallest = right;
281	        if (smallest === parent) break;
282	        this.swap(parent, smallest);
283	        parent = smallest;
284	      }
285	    }
286	    return top;
287	  }
288	
289	  private swap(a: number, b: number): void {
290	    [this.costs[a], this.costs[b]] = [this.costs[b]!, this.costs[a]!];
291	    [this.indexes[a], this.indexes[b]] = [this.indexes[b]!, this.indexes[a]!];
292	  }
293	}
