57	    const hostShip = host.ship()!;
58	    await sleep(300);
59	
60	    // Out of sight: each client decodes only its own ship, both know there are two players, and the room's views
61	    // agree.
62	    expect(guest.visibleShipIds()).toEqual([guest.sessionId]);
