1	import { Client, ErrorCode, type Room } from "@colyseus/sdk";
2	import { matchMaker } from "colyseus";
3	import { afterAll, afterEach, beforeAll, describe, expect, it } from "vitest";
4	import {
5	  MALFORMED_MATCH_REQUEST_MESSAGE,
6	  MATCH_CODE_REQUIRED_MESSAGE,
7	  MATCH_ROOM,
8	  MATCH_UNAVAILABLE_MESSAGE,
9	  matchFullMessage,
10	  NO_SUCH_MATCH_MESSAGE,
11	  PROTOCOL_VERSION,
12	  TEST_PLACEMENT_PATH,
13	} from "@pirate-sea-race/protocol";
14	import { MatchRoom, startGameServer, type MatchMetadata, type RunningGameServer } from "@pirate-sea-race/server";
15	import type { MatchStateSchema } from "@pirate-sea-race/server/schema";
16	import { AHEAD, HeadlessClient, newCreateToken } from "@pirate-sea-race/test-tools";
17	
18	/**
19	 * Private-match admission (skeleton-fixes decisions): a private match can be neither joined nor have a seat reserved
20	 * in it without its code, whichever matchmaker method the caller uses over HTTP.
21	 */
22	let server: RunningGameServer;
23	let endpoint: string;
24	const players: HeadlessClient[] = [];
25	const rooms: Room<unknown, MatchStateSchema>[] = [];
26	
27	async function track(client: Promise<HeadlessClient>): Promise<HeadlessClient> {
28	  const joined = await client;
29	  players.push(joined);
30	  return joined;
31	}
32	
33	beforeAll(async () => {
34	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false });
35	  endpoint = `http://127.0.0.1:${server.port}`;
36	});
37	
38	afterEach(async () => {
39	  await Promise.all(players.splice(0).map((player) => player.leave()));
40	  await Promise.all(rooms.splice(0).map((room) => room.leave(true).catch(() => undefined)));
41	});
42	
43	afterAll(async () => {
44	  await server.close();
45	});
46	
47	type Method = "join" | "joinOrCreate" | "joinById";
48	
49	/** One raw matchmaker request through the SDK, as any HTTP caller could send it. Joined rooms are left afterwards. */
50	async function request(method: Method, target: string, options: Record<string, unknown>): Promise<Room<unknown, MatchStateSchema>> {
51	  const client = new Client(endpoint);
52	  let room: Room<unknown, MatchStateSchema>;
53	  if (method === "join") room = await client.join<MatchStateSchema>(target, options);
54	  else if (method === "joinOrCreate") room = await client.joinOrCreate<MatchStateSchema>(target, options);
55	  else room = await client.joinById<MatchStateSchema>(target, options);
56	  rooms.push(room);
57	  return room;
58	}
59	
60	/** The refusal a request ends with; fails the test if the request succeeds. */
61	async function refusal(attempt: Promise<unknown>): Promise<{ code: unknown; message: string }> {
62	  const error: unknown = await attempt.then(
63	    () => expect.fail("the request was admitted"),
64	    (reason: unknown) => reason,
65	  );
66	  return { code: (error as { code?: unknown }).code, message: (error as Error).message };
67	}
68	
69	function listingOf(roomId: string) {
70	  return matchMaker.query({ roomId });
71	}
72	
73	function roomOf(player: HeadlessClient): MatchRoom {
74	  return matchMaker.getLocalRoomById(player.room.roomId) as unknown as MatchRoom;
75	}
76	
77	/** The host's ship still sails under its own input: the room kept running. */
78	async function expectRunning(host: HeadlessClient): Promise<void> {
79	  expect(host.connected).toBe(true);
80	  const start = host.ship()!;
81	  // Every spawn slot faces open sea, so full ahead from any of them moves the ship.
82	  await host.hold(AHEAD, 300);
83	  await host.waitFor(() => host.ship()!.x !== start.x || host.ship()!.y !== start.y);
84	}
85	
86	describe("private match admission", () => {
87	  it("refuses join, joinOrCreate and joinById without the code, with a wrong code, or with a code and a token", async () => {
88	    const host = await track(HeadlessClient.create(endpoint));
89	    const other = await track(HeadlessClient.create(endpoint));
90	    const unknownCode = host.code === "ZZZZZ9" || other.code === "ZZZZZ9" ? "ZZZZZ8" : "ZZZZZ9";
91	    const version = { protocolVersion: PROTOCOL_VERSION };
92	
93	    for (const method of ["join", "joinOrCreate"] as const) {
94	      expect(await refusal(request(method, MATCH_ROOM, version))).toEqual({ code: 400, message: MALFORMED_MATCH_REQUEST_MESSAGE });
95	      expect(await refusal(request(method, MATCH_ROOM, { ...version, code: unknownCode }))).toEqual({
96	        code: 404,
97	        message: NO_SUCH_MATCH_MESSAGE,
98	      });
99	      expect(await refusal(request(method, MATCH_ROOM, { ...version, code: host.code, createToken: newCreateToken() }))).toEqual({
100	        code: 400,
101	        message: MALFORMED_MATCH_REQUEST_MESSAGE,
102	      });
103	    }
104	
105	    const roomId = host.room.roomId;
106	    expect(await refusal(request("joinById", roomId, version))).toEqual({ code: 400, message: MALFORMED_MATCH_REQUEST_MESSAGE });
107	    expect(await refusal(request("joinById", roomId, { ...version, code: unknownCode }))).toEqual({
108	      code: 404,
109	      message: NO_SUCH_MATCH_MESSAGE,
110	    });
111	    // Another live match's code passes the matchmaker's check but not the room's own.
112	    expect(await refusal(request("joinById", roomId, { ...version, code: other.code }))).toEqual({
113	      code: 404,
114	      message: NO_SUCH_MATCH_MESSAGE,
115	    });
116	    expect(await refusal(request("joinById", roomId, { ...version, code: host.code, createToken: newCreateToken() }))).toEqual({
117	      code: 400,
118	      message: MALFORMED_MATCH_REQUEST_MESSAGE,
119	    });
120	    // A token passes the matchmaker's check as a create, but the room admits only its own creator's token.
121	    expect(await refusal(request("joinById", roomId, { ...version, createToken: newCreateToken() }))).toEqual({
122	      code: 403,
123	      message: MATCH_CODE_REQUIRED_MESSAGE,
124	    });
125	    // A create request that carries a code instead of a token makes no match.
126	    expect(await refusal(new Client(endpoint).create(MATCH_ROOM, { ...version, code: host.code }))).toEqual({
127	      code: ErrorCode.MATCHMAKE_INVALID_CRITERIA,
128	      message: MATCH_UNAVAILABLE_MESSAGE,
129	    });
130	
131	    expect(host.playerCount).toBe(1);
132	    expect(roomOf(host).clients.length).toBe(1);
133	    await expectRunning(host);
134	    // The real code still gets in, by every join method.
135	    const guest = await request("join", MATCH_ROOM, { ...version, code: host.code });
136	    const joinOrCreateGuest = await request("joinOrCreate", MATCH_ROOM, { ...version, code: host.code });
137	    const byIdGuest = await request("joinById", roomId, { ...version, code: host.code });
138	    for (const room of [guest, joinOrCreateGuest, byIdGuest]) expect(room.roomId).toBe(roomId);
139	    await host.waitFor(() => host.playerCount === 4);
140	  });
141	
142	  it("reserves no seat for requests without the code, so players with the code still fill the match", async () => {
143	    const host = await track(HeadlessClient.create(endpoint));
144	    const roomId = host.room.roomId;
145	    const version = { protocolVersion: PROTOCOL_VERSION };
146	    const attempts: Promise<unknown>[] = [];
147	    for (let round = 0; round < 4; round++) {
148	      attempts.push(
149	        refusal(request("join", MATCH_ROOM, version)),
150	        refusal(request("joinOrCreate", MATCH_ROOM, version)),
151	        refusal(request("joinById", roomId, version)),
152	        refusal(request("joinById", roomId, { ...version, createToken: newCreateToken() })),
153	      );
154	    }
155	    await Promise.all(attempts);
156	    const [listing] = await listingOf(roomId);
157	    expect(listing?.clients).toBe(1);
158	    expect(listing?.locked).toBe(false);
159	
160	    for (let seat = 0; seat < 7; seat++) await track(HeadlessClient.join(endpoint, host.code));
161	    await host.waitFor(() => host.playerCount === 8);
162	    await expectRunning(host);
163	  });
164	
165	  it("creates a new match for a joinOrCreate carrying a token, never landing in an existing one", async () => {
166	    const host = await track(HeadlessClient.create(endpoint));
167	    const version = { protocolVersion: PROTOCOL_VERSION };
168	    const created = new Set<string>();
169	    for (let attempt = 0; attempt < 3; attempt++) {
170	      const room = await request("joinOrCreate", MATCH_ROOM, { ...version, createToken: newCreateToken() });
171	      expect(room.roomId).not.toBe(host.room.roomId);
172	      expect(created.has(room.roomId)).toBe(false);
173	      created.add(room.roomId);
174	    }
175	    // A plain join carrying a token matches no listing at all.
176	    expect(await refusal(request("join", MATCH_ROOM, { ...version, createToken: newCreateToken() }))).toEqual({
177	      code: ErrorCode.MATCHMAKE_INVALID_CRITERIA,
178	      message: "no rooms found with provided criteria",
179	    });
180	    expect(host.playerCount).toBe(1);
181	    for (const roomId of created) expect((await listingOf(roomId))[0]?.clients).toBe(1);
182	  });
183	
184	  it("keeps the creator's token out of the listing and admits it once", async () => {
185	    const createToken = newCreateToken();
186	    const creator = await new Client(endpoint).create<MatchStateSchema>(MATCH_ROOM, { protocolVersion: PROTOCOL_VERSION, createToken });
187	    rooms.push(creator);
188	    const listings = await matchMaker.query({ name: MATCH_ROOM });
189	    expect(listings.length).toBeGreaterThan(0);
190	    for (const listing of listings) expect(JSON.stringify(listing)).not.toContain(createToken);
191	    const [own] = await listingOf(creator.roomId);
192	    const room = matchMaker.getLocalRoomById(creator.roomId) as unknown as MatchRoom;
193	    expect(own?.metadata).toEqual({ code: room.state.code, custom: true } satisfies MatchMetadata);
194	    expect(await matchMaker.query({ name: MATCH_ROOM, createToken })).toEqual([]);
195	
196	    // The token was spent on the creator's seat: replaying it does not get a second one.
197	    expect(await refusal(request("joinById", creator.roomId, { protocolVersion: PROTOCOL_VERSION, createToken }))).toEqual({
198	      code: 403,
199	      message: MATCH_CODE_REQUIRED_MESSAGE,
200	    });
201	    // Nor does it lead anyone into this match: a request carrying it can only create another one.
202	    const elsewhere = await request("joinOrCreate", MATCH_ROOM, { protocolVersion: PROTOCOL_VERSION, createToken });
203	    expect(elsewhere.roomId).not.toBe(creator.roomId);
204	    expect(room.clients.length).toBe(1);
205	  });
206	
207	  it("tells the loser of a race for the last seat that the match is full, not that it is missing", async () => {
208	    const host = await track(HeadlessClient.create(endpoint));
209	    for (let seat = 0; seat < 6; seat++) await track(HeadlessClient.join(endpoint, host.code));
210	    const racers = await Promise.allSettled([0, 1, 2].map(() => HeadlessClient.join(endpoint, host.code)));
211	    const joined = racers.flatMap((racer) => (racer.status === "fulfilled" ? [racer.value] : []));
212	    players.push(...joined);
